package android.view;
public abstract class ViewGroup extends View implements ViewParent { public ViewGroup(android.content.Context c){super(c);} public void addView(View v){} public void addView(View v, LayoutParams p){} public void removeView(View v){} public void removeAllViews(){} public static class LayoutParams { public static final int MATCH_PARENT=-1, WRAP_CONTENT=-2; public int width, height; public LayoutParams(int w,int h){} } public static class MarginLayoutParams extends LayoutParams { public int leftMargin, topMargin, rightMargin, bottomMargin; public MarginLayoutParams(int w,int h){super(w,h);} } }
